def backfill_colors_and_seed_donate(apps: Any, schema_editor: Any) -> None:
    """Điền màu mặc định cho các nền tảng hiện có và seed thêm nền tảng Donate cho superuser đầu tiên."""
    platform_model = apps.get_model("finance", "Platform")
    for code, color in DEFAULT_COLOR_MAP.items():
        platform_model.objects.filter(code=code, color="").update(color=color)

    user_model = apps.get_model("system", "User")
    owner = user_model.objects.filter(is_superuser=True, deleted_at__isnull=True).order_by("created_at").first()
    currency = apps.get_model("system", "Currency").objects.filter(is_base=True).first()
    if owner is None or currency is None:
        return

    if not platform_model.objects.filter(owner=owner, code="donate").exists():
        donate = platform_model.objects.create(
            owner=owner,
            code="donate",
            name="Donate",
            color="#DB2777",
            default_currency=currency,
            created_by=owner,
        )
        apps.get_model("finance", "ClassificationRule").objects.create(
            owner=owner,
            name="Nhận diện Donate",
            platform=donate,
            pattern=r"DONATE|UNG\s*HO|QUYEN\s*GOP",
            created_by=owner,
        )
        apps.get_model("finance", "PlatformTaxRate").objects.create(
            platform=donate,
            effective_from=date(2020, 1, 1),
            tax_withheld=False,
            rate=Decimal("0.00"),
            note="Mốc mặc định 0% (không khấu trừ tại nguồn) cho nguồn Donate.",
            created_by=owner,
        )


